message.content:
{
  "css": ".task-form-panel {
  padding: 24px;
}

.editor-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.editor-heading h2 {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
}

#close-task {
  flex-shrink: 0;
  font-size: 14px;
  font-weight: 600;
  min-height: 44px;
  padding: 8px;
  background: transparent;
  border: none;
  color: var(--text);
  cursor: pointer;
}

#close-task:focus-visible {
  outline-offset: 2px;
}

#task-form {
  margin-top: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-field label {
  display: block;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.5;
  margin-bottom: 8px;
  color: var(--text);
}

.field-control {
  background-color: var(--surface);
  border: 1px solid var(--quiet);
  border-radius: 6px;
}

.field-control:focus-within {
  box-shadow: inset 0 0 0 2px var(--focus);
  border-color: transparent;
}

@media (forced-colors: active) {
  .field-control:focus-within {
    outline: 2px solid ButtonText;
    box-shadow: none;
  }
}

#task-name,
#task-category {
  width: 100%;
  min-height: 48px;
  padding: 12px;
  background-color: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  appearance: auto;
}

#task-name {
  box-sizing: border-box;
}

#task-category {
  cursor: pointer;
}

#task-error {
  display: none;
  margin-top: 0;
  color: #d32f2f;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
}

#save-task {
  width: 100%;
  min-height: 52px;
  margin-top: 24px;
  padding: 16px;
  background-color: var(--text);
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  text-align: center;
}

#save-task:focus-visible {
  outline-offset: 2px;
}"
}
